CREATE TABLE `financial_closings` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NULL,`period_from` DATETIME(3) NOT NULL,`period_to` DATETIME(3) NOT NULL,`total_received_cents` BIGINT UNSIGNED NOT NULL,`total_canceled_cents` BIGINT UNSIGNED NOT NULL,`deposit_total_cents` BIGINT UNSIGNED NOT NULL,`manual_in_cents` BIGINT UNSIGNED NOT NULL,`manual_out_cents` BIGINT UNSIGNED NOT NULL,`cash_movements_net_cents` BIGINT NOT NULL,`commissions_total_cents` BIGINT UNSIGNED NOT NULL,`balance_cents` BIGINT NOT NULL,`payment_method_breakdown` JSON NOT NULL,`status` ENUM('ACTIVE', 'CANCELED') NOT NULL DEFAULT 'ACTIVE',`closed_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`closed_by_user_id` BIGINT UNSIGNED NULL,`closed_by_session_id` BIGINT UNSIGNED NULL,`canceled_at` DATETIME(3) NULL,`canceled_reason` VARCHAR(500) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `financial_closings_public_id_key` (`public_id`),INDEX `financial_closings_tenant_id_unit_id_period_from_period_to_idx` (`tenant_id`,`unit_id`,`period_from`,`period_to`),INDEX `financial_closings_tenant_id_status_idx` (`tenant_id`,`status`),CONSTRAINT `financial_closings_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `financial_closings_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `financial_closings_closed_by_user_id_fkey` FOREIGN KEY (`closed_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `financial_closings_closed_by_session_id_fkey` FOREIGN KEY (`closed_by_session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
